previewCss:
.darma-loader-darma-b10-fireflies { --accent: var(--loader-color, #fde047); --accent-2: var(--loader-secondary-color, #a3e635); width: var(--loader-size, 88px); height: var(--loader-size, 88px); position: relative; }
.darma-loader-darma-b10-fireflies span { position: absolute; width: calc(var(--loader-size, 88px) * .1); height: calc(var(--loader-size, 88px) * .1); border-radius: 50%; background: radial-gradient(circle, #fff, var(--accent)); box-shadow: 0 0 calc(var(--loader-size, 88px) * .14) var(--accent); }
.darma-loader-darma-b10-fireflies span:nth-child(odd) { background: radial-gradient(circle, #fff, var(--accent-2)); box-shadow: 0 0 calc(var(--loader-size, 88px) * .14) var(--accent-2); }
.darma-loader-darma-b10-fireflies span:nth-child(1) { left: 8%; top: 20%; animation: darma-loader-darma-b10-fireflies-fly-a calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b10-fireflies span:nth-child(2) { left: 60%; top: 12%; animation: darma-loader-darma-b10-fireflies-fly-b calc(var(--loader-speed, 1s) * 3.4) ease-in-out infinite; }
.darma-loader-darma-b10-fireflies span:nth-child(3) { left: 30%; top: 60%; animation: darma-loader-darma-b10-fireflies-fly-a calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b10-fireflies span:nth-child(4) { left: 72%; top: 64%; animation: darma-loader-darma-b10-fireflies-fly-b calc(var(--loader-speed, 1s) * 3.8) ease-in-out infinite; }
.darma-loader-darma-b10-fireflies span:nth-child(5) { left: 46%; top: 38%; animation: darma-loader-darma-b10-fireflies-fly-a calc(var(--loader-speed, 1s) * 3.2) ease-in-out infinite; }
@keyframes darma-loader-darma-b10-fireflies-fly-a { 0%, 100% { transform: translate(0, 0); opacity: .3; } 25% { transform: translate(55%, 25%); opacity: 1; } 50% { transform: translate(20%, 60%); opacity: .5; } 75% { transform: translate(-25%, 35%); opacity: 1; } }
@keyframes darma-loader-darma-b10-fireflies-fly-b { 0%, 100% { transform: translate(0, 0); opacity: 1; } 30% { transform: translate(-45%, 30%); opacity: .4; } 60% { transform: translate(-15%, -35%); opacity: 1; } 80% { transform: translate(30%, -20%); opacity: .6; } }

